def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_last = my[-1]
    opp_last = opp[-1]

    opp_c = opp.count('C')
    opp_rate = (opp_c + 1.0) / (n + 2.0)

    rec = opp[-10:]
    rec_len = len(rec)
    rec_d = rec.count('D')
    rec_c = rec_len - rec_d

    opp_D = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_D += 1
        i -= 1

    opp_C = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        opp_C += 1
        i -= 1

    my_D = 0
    i = n - 1
    while i >= 0 and my[i] == 'D':
        my_D += 1
        i -= 1

    mutual_D = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and opp[i] == 'D':
        mutual_D += 1
        i -= 1

    start = max(1, n - 12)
    dc = 0
    dd = 0
    match = 0
    total = 0
    for i in range(start, n):
        prev_my = my[i - 1]
        cur_opp = opp[i]
        if prev_my == 'D':
            if cur_opp == 'C':
                dc += 1
            else:
                dd += 1
        if prev_my == cur_opp:
            match += 1
        total += 1

    match_rate = (match / total) if total > 0 else 1.0

    if opp_rate <= 0.25 or rec_d >= 8 or opp_D >= 8:
        return 'D'

    if rec_d > 0 and rec_c > 0 and match_rate < 0.75:
        seg = opp[-12:] if n >= 12 else opp[:]
        seg_len = len(seg)
        if seg_len >= 8:
            period = False
            for p in range(2, min(6, seg_len - 1) + 1):
                t = seg_len - p
                if t >= 4:
                    ok = 0
                    for j in range(t):
                        if seg[j] == seg[j + p]:
                            ok += 1
                    if ok == t or ok * 10 >= t * 9:
                        period = True
                        break
            if period:
                return 'D'

    if opp_D >= 4:
        return 'D'

    if opp_D == 0 and opp_C >= 2 and my_D >= 2 and dc >= 1 and opp_rate > 0.60:
        return 'D'

    if dc >= 2 and dc > dd and rec_c >= rec_d and opp_rate > 0.55:
        return 'D'

    if (n >= 2 and my_last == 'D' and opp_last == 'C' and my_D == 1 and
            opp[n - 2] == 'D' and rec_d >= 3 and opp_rate > 0.55):
        return 'D'

    if my_last == 'D' and opp_last == 'C' and my_D == 1 and rec_d == 0 and opp_C >= 5:
        return 'D'

    if (opp_c == n and opp_C >= 10 and my_D == 0 and opp_D == 0 and n >= 25 and n <= 85 and
            (n == 25 or rng.random() < 0.02)):
        return 'D'

    if my_last == 'D' and opp_last == 'D':
        if opp_D >= 5 or rec_d >= 6 or opp_rate <= 0.40:
            return 'D'
        if dd >= 1 and dc == 0 and opp_rate > 0.50:
            return 'C'
        if mutual_D >= 3 and opp_rate > 0.50:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if n >= 2 and my[n - 2] == 'D' and opp_D <= 2:
            return 'C'
        if opp_D >= 2 and opp_rate <= 0.65:
            return 'D'
        if opp_rate >= 0.60 and rec_d <= 3:
            return 'C'
        return 'D'

    if my_last == 'D':
        return 'C'

    return 'C'
